export function createAdminService(accounts){const client=accounts.client;
 async function checked(q){const {data,error}=await q;if(error)throw Error(error.message);return data;}
 async function user(){const u=await accounts.user({fresh:true});if(!u)throw Error('Sign in to access finance administration.');return u;}
 async function isAdmin(){const u=await user();return !!(await checked(client.from('finance_admin_memberships').select('user_id').eq('user_id',u.id).maybeSingle()));}
 async function directory(query=''){await user();return checked(client.rpc('finance_account_directory',{query}));}
 async function load({filter='queue',page=0,accountId='',kind='all'}={}){await user();if(!await isAdmin())throw Error('Administrator access required.');let requests=client.from('funding_requests').select('*,amount::text,fee::text,network_fee::text').order('created_at',{ascending:filter==='queue'}).range(page*50,page*50+49);if(filter==='queue')requests=requests.in('status',['pending_review','processing']);if(filter==='completed')requests=requests.in('status',['confirmed','paid']);if(filter==='closed')requests=requests.in('status',['rejected','cancelled']);if(kind!=='all')requests=requests.eq('kind',kind);if(accountId)requests=requests.eq('user_id',accountId);let balances=client.from('wallet_balances').select('user_id,asset,available::text,reserved::text').order('asset').limit(200),ledger=client.from('wallet_ledger').select('*,available_delta::text,reserved_delta::text').order('created_at',{ascending:false}).limit(50);if(accountId){balances=balances.eq('user_id',accountId);ledger=ledger.eq('user_id',accountId);}const [rows,wallets,entries,commands]=await Promise.all([checked(requests),checked(balances),checked(ledger),checked(client.from('finance_admin_commands').select('*,amount::text,network_fee::text').order('created_at',{ascending:false}).limit(30))]);return {requests:rows,balances:wallets,ledger:entries,commands};}
 async function execute(action,values,id){await user();const existing=await checked(client.from('finance_admin_commands').select('*').eq('id',id).maybeSingle());if(existing)return existing;const row=await checked(client.from('finance_admin_commands').insert({id,action,...values}).select().single());window.dispatchEvent(new Event('wallet-updated'));return row;}
 return {isAdmin,directory,load,execute};}
